package operators;

public class Assignment_operator {
	public static void main(String[] args) {
		// TODO Auto-generated method stub
	    int a = 20;
        a += 10;
        System.out.println("After += : " + a);
        a -= 5;
        System.out.println("After -= : " + a);
        a *= 2;
        System.out.println("After *= : " + a);
        a /= 5;
        System.out.println("After /= : " + a);
	}
}
